/*<info serverAlias="DBCUST-CustDB"></info>*/
/*
	Created: Johnson@20230216
	Task: Migrate TLC to KzingP88 [redmine: #183871]
	DB: DBCust/CustDB
*/
ALTER PROCEDURE [dbo].Acc_ExecRep_Cust_19
	@custids VARCHAR(MAX)	
	,@target VARCHAR(20)
AS
BEGIN
	SET NOCOUNT ON
	
	IF (@target = 'REPLICATED' AND @@SERVERNAME IN ('DBCUST','SITDBCUST','TESTDBCUST','DBSPARE')) RETURN	-- run at all replicated servers
	IF (@target = 'DBCUST' AND @@SERVERNAME NOT IN ('DBCUST','SITDBCUST','TESTDBCUST','DBSPARE')) RETURN -- run at dbcust only
		
	IF dbo.f_CheckRepTable('Customer') = 0 RETURN
	
	CREATE TABLE #tblCust (custid1 INT PRIMARY KEY, custid2 INT)
	
	DECLARE @xml XML = CAST (@custids as XML)
	
	INSERT INTO #tblCust(custid1,custid2)
	SELECT T.c.query('.').value('(r/@id1)[1]', 'int') AS id1,
	T.c.query('.').value('(r/@id2)[1]', 'int') AS id2
	FROM   @xml.nodes('/Root/r') T(c)  
	
	UPDATE cs2
	SET cs2.ugroup = cs1.ugroup
	FROM customer cs2 WITH(ROWLOCK)
		INNER JOIN #tblCust t ON cs2.custid = t.custid2
		INNER JOIN customer cs1 WITH(NOLOCK) ON cs1.custid = t.custid1
		
	IF dbo.f_CheckRepTable('Dep_CustBetSettingGame_Member') = 0 RETURN		
	IF dbo.f_CheckRepTable('Dep_CustBetSetting_Member') = 0 RETURN		
		
	UPDATE cs2
	SET cs2.minbet = cs1.minbet,
		cs2.maxbet = cs1.maxbet,
		cs2.maxpermatch = cs1.maxpermatch,
		cs2.MaxPerNumber = cs1.MaxPerNumber,
		cs2.MaxPayoutPerMatch = cs1.MaxPayoutPerMatch
	FROM Dep_CustBetSettingGame_Member cs2 WITH(ROWLOCK)
		INNER JOIN #tblCust t ON cs2.custid = t.custid2
		INNER JOIN Dep_CustBetSettingGame_Member cs1 WITH(NOLOCK) ON cs1.custid = t.custid1
													AND cs1.sporttype = cs2.sporttype
													AND cs1.bettype = cs2.bettype																								
	WHERE cs2.sporttype IN (1,2,3,5,8,10,11,43,99,99,9901,9902,161)
	
	UPDATE cs2
	SET cs2.minbet = cs1.minbet,
		cs2.maxbet = cs1.maxbet,
		cs2.maxpermatch = cs1.maxpermatch
	FROM Dep_CustBetSetting_Member cs2 WITH(ROWLOCK)
		INNER JOIN #tblCust t ON cs2.custid = t.custid2
		INNER JOIN Dep_CustBetSetting_Member cs1 WITH(NOLOCK) ON cs1.custid = t.custid1
													AND cs1.sporttype = cs2.sporttype
													AND cs1.bettype = cs2.bettype																								
	WHERE cs2.sporttype IN (180,181,182,183,184,185,186,190,191,199,202)		
END	
GO
-- END STEP 1: DEPLOY THIS SP @DBCUST.CustDB --------
------------------------------------------------------	

-- BEGIN STEP 2: RUN THIS SCRIPT AT ALL REPLICATED SERVERS -----
--------------------------------------------------------------------------------------
PRINT N'Step 2: Start on ' + CAST(GETDATE() AS NVARCHAR(30)) + N'.';  

DECLARE @target VARCHAR(20)
IF @@SERVERNAME IN ('DBCUST','SITDBCUST','TESTDBCUST','DBSPARE')
	SET @target = 'DBCUST'
ELSE 
	SET @target = 'REPLICATED'

Print 'Server Name : ' + @target

