SELECT val
INTO #temp
FROM dbo.f_SplitString(@string, ',')
OPTION (MAXRECURSION 0)

SELECT LEFT(LTRIM(val), CHARINDEX('CC', val) - 1) AS custidTLC, RIGHT (val, len (val) - (CHARINDEX('CC', val) + 1) ) AS custidP88
INTO #tblCust2
FROM #temp

INSERT INTO #tmpCust(custidTLC,custidP88)
select replace (replace(replace(custidTLC,char(9),''),char(13),''),char(10),'') as custidM88, replace (replace(replace(custidP88,char(9),''),char(13),''),char(10),'') as custidP88
from #tblCust2


DECLARE @custids VARCHAR(MAX) = ''
DECLARE @tmp TABLE (custidTLC INT,custidP88 INT)

WHILE(1=1)
BEGIN		
	DELETE @tmp	
	
	UPDATE TOP(300) t	
	SET isFinished = 1
	OUTPUT DELETED.custidTLC, DELETED.custidP88 INTO @tmp(custidTLC,custidP88)
	FROM #tmpCust t
	WHERE isFinished = 0
	
	IF @@rowcount = 0
		BREAK;
		
	SELECT @custids =(
		SELECT custidTLC as '@id1', custidP88 '@id2'
		FROM @tmp
		FOR XML PATH('r'), ROOT('Root')
	)
	
	EXEC Acc_ExecRep_Cust_19 @custids = @custids,
							@target = @target
	
	WAITFOR DELAY '0:0:0.028'						
	
END
